(* [comment removed for export] *)
Lemma Forall_rin_self : forall XS : list (Z * Z), Forall (fun iv : Z * Z => forall a, fst iv <= a < snd iv -> rin_ivs XS a) XS.
Proof.
  induction XS as [|iv XS IH]; [apply Forall_nil|]. apply Forall_cons; [intros a Ha; cbn; left; exact Ha|].
  eapply Forall_impl; [| exact IH]. intros iv' K a Ha. cbn. right. exact (K a Ha).
Qed.

Lemma AConfigSvc_cons_LB {HCEIL : HeapCeil} : forall LB b m c S, AConfigSvc LB m c S -> AConfigSvc (b :: LB) m c S.
Proof. intros LB b m c S (p & j4 & j7 & IN & K). exists p, j4, j7. split; [right; exact IN| exact K]. Qed.

(* [comment removed for export] *)
Definition ASchedTail {HCEIL : HeapCeil} (m : mem) (S : Z) : Prop :=
  exists j50 jm j109 je jt j219,
     rw_cells bsegs m (S + O_SCH_ONE_THREAD) [CB 2 [b8 0; b8 0]; CB 6 j50]
  /\ rw_cells bsegs m (S + O_SCH_MUTEX) [CB 8 jm]
  /\ APMutex m (S + O_SCH_PMUTEX) 0
  /\ rw_cells bsegs m (S + O_SCH_SPIN) [C4 (wz 0); CB 1 [b8 1]; CB 3 j109]
  /\ rw_cells bsegs m (S + O_SCH_EVENT) [CB 8 je]
  /\ APCond m (S + O_SCH_COND) CLOCK_MONOTONIC
  /\ rw_cells bsegs m (S + O_SCH_EVSTATE)
       [C8 (wz 0); C8 (wz 0); C8 (wz P_A_SCHED_GET_DEFAULT_TASK); C8 (wz 0); C8 (wz 0); C4 (wz 0); CB 4 jt;
        CB 3 [b8 1; b8 0; b8 0]; CB 5 j219; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max); C8 (wz 0)].

Lemma ASchedCells_split {HCEIL : HeapCeil} : forall m S ioc, ASchedCells m S ioc -> rw_cells bsegs m S (SvcHdrCells (sched_hdr0 ioc)) /\ ASchedTail m S.
Proof. intros m S ioc (j50 & jm & j109 & je & jt & j219 & K0 & K). split; [exact K0| exists j50, jm, j109, je, jt, j219; exact K]. Qed.
